export const DELETE = Symbol('delete');

function isOrdinaryObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    (Object.getPrototypeOf(value) === Object.prototype ||
      Object.getPrototypeOf(value) === null)
  );
}

function cloneInner(value, inArray) {
  if (value === undefined || value === DELETE) {
    throw new TypeError('invalid value');
  }
  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
    return value;
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError('invalid value');
    return value;
  }
  if (typeof value === 'function' || typeof value === 'symbol') {
    throw new TypeError('invalid value');
  }
  if (Array.isArray(value)) {
    const out = [];
    for (const item of value) {
      out.push(cloneInner(item, true));
    }
    return out;
  }
  if (isOrdinaryObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) {
      const prop = value[key];
      if (prop === undefined || prop === DELETE) continue;
      out[key] = cloneInner(prop, false);
    }
    return out;
  }
  throw new TypeError('invalid value');
}

export function cloneValue(value) {
  if (value === undefined || value === DELETE) {
    throw new TypeError('invalid value');
  }
  return cloneInner(value, false);
}

