import { cloneValue, DELETE } from './clone-value.mjs';

export { DELETE };

function isOrdinaryObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    (Object.getPrototypeOf(value) === Object.prototype ||
      Object.getPrototypeOf(value) === null)
  );
}

function validateContent(value) {
  if (value === undefined || value === DELETE) return;
  if (value === null || typeof value === 'boolean' || typeof value === 'string') return;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError('invalid layer content');
    return;
  }
  if (typeof value === 'function' || typeof value === 'symbol') {
    throw new TypeError('invalid layer content');
  }
  if (Array.isArray(value)) {
    for (const item of value) {
      if (item === undefined || item === DELETE) {
        throw new TypeError('invalid layer content');
      }
      validateContent(item);
    }
    return;
  }
  if (isOrdinaryObject(value)) {
    for (const key of Object.keys(value)) {
      validateContent(value[key]);
    }
    return;
  }
  throw new TypeError('invalid layer content');
}

function mergeInto(target, layer) {
  for (const key of Object.keys(layer)) {
    const incoming = layer[key];
    if (incoming === undefined) continue;
    if (incoming === DELETE) {
      delete target[key];
      continue;
    }
    const previous = target[key];
    if (isOrdinaryObject(previous) && isOrdinaryObject(incoming)) {
      mergeInto(previous, incoming);
      continue;
    }
    target[key] = cloneValue(incoming);
  }
}

export function mergeLayers(...layers) {
  const out = {};
  for (const layer of layers) {
    if (layer === undefined) continue;
    if (!isOrdinaryObject(layer)) {
      throw new TypeError('invalid layer');
    }
    validateContent(layer);
    mergeInto(out, layer);
  }
  return cloneValue(out);
}

